{
  "components": [
    {
      "type": "claim",
      "quote": "Bei umfangreichen oder nicht hinreichend definierten Anfragen kann das BFE verlangen, das Gesuch zu präzisieren.",
      "gist": "BFE can request clarification for extensive or poorly defined requests."
    },
    {
      "type": "number",
      "quote": "20 Tagen",
      "gist": "20 days"
    },
    {
      "type": "claim",
      "quote": "Wir nehmen innert 20 Tagen Stellung zum Gesuch.",
      "gist": "We respond to the request within 20 days."
    },
    {
      "type": "condition",
      "quote": "Die Frist kann verlängert werden; in diesem Fall werden Sie über die Verlängerung informiert.",
      "gist": "The deadline can be extended, and you will be informed of the extension."
    },
    {
      "type": "claim",
      "quote": "Das Zugangsverfahren ist im Öffentlichkeitsgesetz und in der Verordnung zum Öffentlichkeitsgesetz geregelt.",
      "gist": "Access procedure is regulated by the Public Information Act and its ordinance."
    },
    {
      "type": "other",
      "quote": "Mit dem unten angehängten Gesuchsformular können Sie schriftlich per E-Mail oder Briefpost den Zugang zu amtlichen Dokumenten beantragen.",
      "gist": "You can apply for access to official documents in writing via email or mail using the attached form."
    }
  ]
}
